{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "fourmis-marketplace",
  "description": "Curated plugins for Claude Code built by the Fourmis community. Multi-agent productivity tools, developer utilities, and workflow automation.",
  "owner": {
    "name": "Fourmis",
    "email": "javier-canizalez@outlook.com"
  },
  "plugins": [
    {
      "name": "hello-world",
      "description": "A simple demo plugin that greets the user and demonstrates the Claude Code plugin standard. Includes a slash command and an auto-activating skill.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/hello-world",
      "category": "demo"
    },
    {
      "name": "git-workflow",
      "description": "Smart git workflows: conventional commits, branch naming conventions, PR description templates, and changelog generation. Enforces consistent practices across your team.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/git-workflow",
      "category": "productivity"
    },
    {
      "name": "code-health",
      "description": "Codebase quality metrics and tech debt tracking. Analyzes file complexity, outdated dependencies, TODO/FIXME markers, and dead code. Gives your codebase a health score with actionable improvements.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/code-health",
      "category": "productivity"
    },
    {
      "name": "api-docs",
      "description": "Auto-generate API documentation from your code. Scans route handlers in Express, Go, Next.js, and Fastify to produce OpenAPI specs, markdown references, and curl examples.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/api-docs",
      "category": "development"
    },
    {
      "name": "reddit-mcp",
      "description": "Full Reddit integration via MCP — browse subreddits, search posts, read comments, submit posts, comment, and vote. Authenticated via OAuth2 with 10 tools covering all core Reddit operations.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/reddit-mcp",
      "category": "social"
    },
    {
      "name": "local-crm",
      "description": "Local-first CRM for freelancers — manage contacts, deals, follow-ups, and interactions with zero cloud dependencies. SQLite-based with 17 MCP tools covering full CRUD, pipeline tracking, and reporting.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/local-crm",
      "category": "productivity"
    },
    {
      "name": "markdown-writer",
      "description": "Professional writing toolkit — blog posts, technical docs, SEO content, readability analysis, content outlining, and systematic editing. 6 skills, 3 commands, 1 editor agent. No dependencies.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/markdown-writer",
      "category": "content"
    },
    {
      "name": "devops-skills",
      "description": "Comprehensive DevOps expertise bundle — incident response, deployment safety, Dockerfile optimization, GitHub Actions, Kubernetes troubleshooting, security hardening, and infrastructure cost analysis. 7 skills, 3 commands, 2 agents.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/devops-skills",
      "category": "devops"
    },
    {
      "name": "social-poster",
      "description": "Cross-platform social media posting — publish to Bluesky and Mastodon from Claude Code. Compose once, adapt for character limits, post to one or all platforms. 8 MCP tools, 1 skill, 2 commands.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/social-poster",
      "category": "social"
    },
    {
      "name": "seo-toolkit",
      "description": "Free SEO analysis toolkit — on-page optimization, technical audits, meta tag validation, heading analysis, image audits, SSL checks, redirect tracing, robots.txt/sitemap parsing, and performance metrics. 10 MCP tools, 3 skills, 2 commands, 1 agent. No paid API keys.",
      "version": "1.0.0",
      "author": {
        "name": "Fourmis"
      },
      "source": "./plugins/seo-toolkit",
      "category": "marketing"
    }
  ]
}
